using System;using System.IO;using System.Linq;using System.Collections.Generic;using Newtonsoft.Json;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.VFX;using UnityEngine.SceneManagement;using GameActions;
namespace AssetPipeline.Editor
{
 [InitializeOnLoad]public static class CombatVFXValidation
 {
  const string Stage="AssetStaging/VFXUpgrade/",Key="CombatVFXValidation",Root="Assets/Game/VFX/Combat/";static int phase;static float at;static Camera camera;static readonly List<object> checks=new List<object>();
  static CombatVFXValidation(){EditorApplication.update+=Poll;EditorApplication.playModeStateChanged+=Mode;}
  static void Mode(PlayModeStateChange m){if(m==PlayModeStateChange.EnteredEditMode){SessionState.SetBool(Key,false);SessionState.SetBool(Key+"Ready",false);}if(m==PlayModeStateChange.EnteredPlayMode){SessionState.SetBool(Key+"Ready",true);phase=0;}if(m==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool(Key+"Restore",false)){EditorSceneManager.playModeStartScene=AssetDatabase.LoadAssetAtPath<SceneAsset>(SessionState.GetString(Key+"Prior",""));SessionState.SetBool(Key+"Restore",false);string original=SessionState.GetString(Key+"OriginalScene","");if(!string.IsNullOrEmpty(original))EditorApplication.delayCall+=()=>EditorSceneManager.OpenScene(original,OpenSceneMode.Single);}}
  static void Check(bool condition,string name){if(!condition)throw new Exception(name);checks.Add(new{name,passed=true});}
  static void Poll()
  {
   if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;
   if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Stage+"VFXCheck.request")){File.Delete(Stage+"VFXCheck.request");SessionState.SetBool(Key,true);SessionState.SetBool(Key+"Ready",false);SessionState.SetString(Key+"OriginalScene",SceneManager.GetActiveScene().path);for(int i=0;i<SceneManager.sceneCount;i++){var scene=SceneManager.GetSceneAt(i);if(scene.isDirty)EditorSceneManager.SaveScene(scene,Stage+"Backup/UnsavedBeforeVFX_"+i+".unity",true);}SessionState.SetBool(Key+"Restore",true);SessionState.SetString(Key+"Prior",AssetDatabase.GetAssetPath(EditorSceneManager.playModeStartScene));EditorSceneManager.playModeStartScene=AssetDatabase.LoadAssetAtPath<SceneAsset>(Root+"Preview/CombatVFXReview.unity");EditorApplication.EnterPlaymode();return;}
   if(!Application.isPlaying||!SessionState.GetBool(Key,false)||!SessionState.GetBool(Key+"Ready",false)||Time.timeSinceLevelLoad<.5f)return;
   try{Run();}catch(Exception e){Finish(false,e.ToString());}
  }
  static void Shot(string name,Vector3 eye,Vector3 target)
  {
   camera.transform.SetPositionAndRotation(eye,Quaternion.LookRotation(target-eye));var rt=RenderTexture.GetTemporary(1280,720,24,RenderTextureFormat.ARGB32);var old=RenderTexture.active;camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(Stage+name+".png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);camera.targetTexture=null;RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);
  }
  static void Run()
  {
   if(phase==0){Application.runInBackground=true;Cursor.lockState=CursorLockMode.None;camera=Camera.main;checks.Clear();var loop=UnityEngine.Object.FindFirstObjectByType<VFXReviewLoop>();if(!loop){EditorSceneManager.LoadSceneInPlayMode(Root+"Preview/CombatVFXReview.unity",new LoadSceneParameters(LoadSceneMode.Single));return;}Check(loop,"Review scene loaded");loop.enabled=false;foreach(var p in UnityEngine.Object.FindObjectsByType<ParticleSystem>(FindObjectsSortMode.None))if(!p.main.loop)p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);foreach(var v in UnityEngine.Object.FindObjectsByType<VisualEffect>(FindObjectsSortMode.None))v.Stop();var graph=AssetDatabase.LoadAssetAtPath<Shader>(Root+"Graphs/ResonanceRefraction.shadergraph");Check(graph&&!ShaderUtil.GetShaderMessages(graph).Any(m=>m.severity==UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error),"Refraction Shader Graph compiles");var shards=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"VioletCrystalDebris.prefab");Check(shards.GetComponentInChildren<ParticleSystemRenderer>().mesh.triangles.Length==24,"Each cosmetic crystal has eight triangles");Check(shards.GetComponentsInChildren<Collider>().Length==0&&shards.GetComponentsInChildren<CrystalParkour.CrystalSurface>().Length==0,"Cosmetic crystals have no pickup or gameplay collider");at=Time.time;phase=1;return;}
   if(phase==1){if(Time.time-at<1)return;CombatEffects.Emit(CombatEffect.Sparks,new Vector3(-4,.3f,0),Vector3.up);CombatEffects.Emit(CombatEffect.PurpleBlood,new Vector3(0,1.5f,0),Vector3.up,1.6f);CombatEffects.Emit(CombatEffect.CrystalShards,new Vector3(0,1.5f,0),Vector3.up);var wave=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"RefractiveShockwave.prefab"));wave.transform.position=new Vector3(0,.08f,0);wave.GetComponent<ICombatWave>().Begin(5,1.5f);var rubble=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"ConcreteImpactHeavy.prefab");if(rubble)CombatEffects.Burst(rubble,new Vector3(4,.08f,1),Vector3.up,1,8);at=Time.time;phase=2;return;}
   if(phase==2){if(Time.time-at<.1f)return;Shot("sparks_early",new Vector3(-4,1.6f,-4),new Vector3(-4,.6f,0));var gpu=UnityEngine.Object.FindFirstObjectByType<VisualEffect>();Check(gpu&&gpu.aliveParticleCount>=40,"GPU sparks emit dozens of live particles");Check(gpu.HasVector3("GroundPoint")&&gpu.GetVector3("GroundPoint").y<0,"GPU ground collider is bound below impact");var flash=UnityEngine.Object.FindFirstObjectByType<VFXLightPulse>();Check(flash&&flash.GetComponent<Light>().shadows==LightShadows.None&&flash.GetComponent<Light>().intensity>0,"Orange spark flash lights without shadows");phase=3;return;}
   if(phase==3){if(Time.time-at<.4f)return;Shot("blood_wave",new Vector3(7,4,-8),new Vector3(0,1.2f,0));Shot("ground_impact_dust",new Vector3(7,2.4f,-3),new Vector3(4,.3f,1));Shot("sparks_falling",new Vector3(-4,1.8f,-4),new Vector3(-4,.3f,0));var particles=UnityEngine.Object.FindObjectsByType<ParticleSystem>(FindObjectsSortMode.None);Check(particles.Any(p=>p.name.Contains("violet blood")&&p.particleCount>=8),"Purple flipbook mist is alive");Check(particles.Any(p=>p.name.Contains("96 colliding")&&p.particleCount>=80&&p.collision.enabled),"More than eighty crystal particles use world collision");phase=4;return;}
   if(phase==4){if(Time.time-at<1.15f)return;Shot("shockwave_late",new Vector3(7,4,-8),new Vector3(0,1.2f,0));Shot("lightning",new Vector3(-12,5,-1),new Vector3(-5,2.2f,7));Shot("steam",new Vector3(8,2,-1),new Vector3(5,1.2f,3));Shot("crater",new Vector3(6,3,-2),new Vector3(4,.05f,1));var arcs=UnityEngine.Object.FindFirstObjectByType<SurfaceLightning>();Check(arcs&&arcs.GetComponentsInChildren<LineRenderer>().Length==14,"Seven animated lightning bolts have core and glow");Check(arcs.GetComponentsInChildren<Light>().All(l=>l.shadows==LightShadows.None),"Lightning point lights do not cast shadows");phase=5;return;}
   if(phase==5){if(Time.time-at<5)return;var p=UnityEngine.Object.FindObjectsByType<ParticleSystem>(FindObjectsSortMode.None).First(x=>x.name.Contains("96 colliding"));var buffer=new ParticleSystem.Particle[256];int n=p.GetParticles(buffer);File.WriteAllText(Stage+"crystal_positions.json",JsonConvert.SerializeObject(buffer.Take(n).Select(x=>new{x=x.position.x,y=x.position.y,z=x.position.z}),Formatting.Indented));Check(n>0&&buffer.Take(n).All(x=>x.position.y>-.15f),"Crystal debris stays above the floor after five seconds");Shot("settled_crystals",new Vector3(4,2,-4),new Vector3(0,.1f,1));Finish(true);}
  }
  static void Finish(bool passed,string error=null){File.WriteAllText(Stage+"vfx_validation.json",JsonConvert.SerializeObject(new{passed,error,checks},Formatting.Indented));SessionState.SetBool(Key,false);phase=0;EditorApplication.ExitPlaymode();}
 }
}

